def comp8(grid,cells):
    cells=set(cells);res=[]
    while cells:
        s=next(iter(cells));st=[s];cells.discard(s);c=[s]
        while st:
            y,x=st.pop()
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    n=(y+dy,x+dx)
                    if n in cells: cells.discard(n);st.append(n);c.append(n)
        res.append(c)
    return res
